// Four enquiries of the kind a small service business actually receives.
// In production this node is replaced by a Webhook (contact form) or a Gmail
// trigger — everything downstream is unchanged.

const samples = [
  {
    received_at: '2026-07-28T09:14:00Z',
    from: 'l.hartley@brightpath-dental.co.uk',
    subject: 'Automating our appointment reminders',
    enquiryText: `Hi,\n\nWe run three dental practices in Essex and we are still phoning patients to remind them about appointments. It is eating about 15 hours a week of reception time and we still get no-shows.\n\nWe use Dentally for bookings and Twilio for texts already. Is this something you could connect up so reminders go out automatically, with a confirm or reschedule reply?\n\nWe would want it live before the end of September. Budget is somewhere around 2,000 to 3,000 pounds if that is realistic.\n\nLouise Hartley\nPractice Manager`
  },
  {
    received_at: '2026-07-28T11:02:00Z',
    from: 'ops@vantage-logistics.com',
    subject: 'Re: workflow stopped last night',
    enquiryText: `Morning — the stock sync you set up threw an error at about 23:40 and has not run since. Nothing has changed our end as far as I know. Can you take a look today? We are flying blind on stock levels until it is back.\n\nThanks, Dan`
  },
  {
    received_at: '2026-07-28T11:40:00Z',
    from: 'growth@leadrocket-outreach.biz',
    subject: 'Quick question',
    enquiryText: `Hi there,\n\nI came across your profile and wanted to reach out. We help agencies book 30-50 qualified calls per month on autopilot using our proven AI outreach system.\n\nWorth a quick 15 min chat this week?\n\nUnsubscribe here.`
  },
  {
    received_at: '2026-07-28T14:26:00Z',
    from: 'r.okafor@nimbus-talent.co.uk',
    subject: 'Automation Engineer role — 65k, hybrid Cambridge',
    enquiryText: `Hi,\n\nI am recruiting for an Automation Engineer position with a scale-up near Cambridge. Salary to 65k, hybrid three days on site. Your background looked like a strong fit.\n\nAre you open to a conversation?\n\nRachel Okafor, Nimbus Talent`
  }
];

return samples.map(s => ({ json: s }));

// Deterministic prioritisation. The model reads and extracts; the ranking
// rules live here in plain code so they are auditable and adjustable by the
// client without touching a prompt.

const SCORING = {
  budgetTiers: [
    { min: 2000, points: 40, label: 'budget >= 2k' },
    { min: 750,  points: 28, label: 'budget >= 750' },
    { min: 1,    points: 15, label: 'budget stated' }
  ],
  painPerHour: 1.5,     // points per claimed manual hour per week
  painCap: 25,
  deadlinePoints: 15,
  systemsPoints: 10,    // named tools => a concrete, scopeable integration
  identifiedPoints: 5
};

const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const reasons = [];
  let score = 0;

  const budget = Number(d.budget_stated) || 0;
  const tier = SCORING.budgetTiers.find(t => budget >= t.min);
  if (tier) { score += tier.points; reasons.push(`${tier.label} (+${tier.points})`); }
  else reasons.push('no budget stated (+0)');

  const hours = Number(d.manual_hours_claimed) || 0;
  if (hours > 0) {
    const pts = Math.min(Math.round(hours * SCORING.painPerHour), SCORING.painCap);
    score += pts;
    reasons.push(`${hours}h/week manual pain (+${pts})`);
  }

  if (d.deadline_mentioned) {
    score += SCORING.deadlinePoints;
    reasons.push(`deadline "${d.deadline_mentioned}" (+${SCORING.deadlinePoints})`);
  }

  const systems = (d.systems_mentioned || '').split(',').map(s => s.trim()).filter(Boolean);
  if (systems.length) {
    score += SCORING.systemsPoints;
    reasons.push(`${systems.length} named system(s) (+${SCORING.systemsPoints})`);
  }

  if (d.contact_name && d.organisation) {
    score += SCORING.identifiedPoints;
    reasons.push(`identified sender (+${SCORING.identifiedPoints})`);
  }

  const priority = score >= 70 ? 'A — reply today'
                 : score >= 40 ? 'B — reply within 48h'
                 : 'C — reply when convenient';

  // Questions that must be answered before this can be quoted at a fixed price.
  const blockers = [];
  if (!budget) blockers.push('No budget indicated — ask for a range before scoping');
  if (!systems.length) blockers.push('No systems named — cannot assess integration effort');
  if (!d.deadline_mentioned) blockers.push('No deadline — confirm urgency');

  out.push({
    json: {
      ...d,
      systems_list: systems,
      lead_score: score,
      priority,
      score_reasons: reasons,
      scoping_blockers: blockers,
      original_from: $('Load Sample Enquiries').item.json.from,
      original_subject: $('Load Sample Enquiries').item.json.subject
    }
  });
}

return out;

parameters.text:
=Write a short reply to this enquiry, to be reviewed and sent by a freelance automation developer.

What they wrote:
---
{{ $('Load Sample Enquiries').item.json.enquiryText }}
---

What was understood:
- Problem: {{ $json.problem_summary }}
- Systems named: {{ $json.systems_list.join(', ') || 'none named' }}
- Budget stated: {{ $json.budget_stated ? '£' + $json.budget_stated : 'none stated' }}
- Deadline: {{ $json.deadline_mentioned || 'none stated' }}
- Still unknown: {{ $json.scoping_blockers.join('; ') || 'nothing material' }}

Rules for the reply:
- 90 to 130 words. Plain English. No marketing language.
- Open by restating their problem accurately, so they can see it was read properly.
- Say concretely how the problem would be approached, referencing the systems they actually named.
- Never claim past clients, past projects, years of experience, team size or results. There are none to cite. Write from capability, not history.
- Never state a price, a delivery date or a guarantee.
- End with exactly one question — the single unknown that most affects the quote.
- Sign off as Ben. No job title.

Return only the reply text.
